<?php require_once __DIR__.'/../app/core/bootstrap.php';$u=require_role(['operator']);$action=$_POST['action']??'';
function operator_upload_image(string $field,string $fallback): string { if(empty($_FILES[$field]['name']) || ($_FILES[$field]['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK) return $fallback; if($_FILES[$field]['size']>4*1024*1024) return $fallback; $ext=strtolower(pathinfo($_FILES[$field]['name'],PATHINFO_EXTENSION)); if(!in_array($ext,['jpg','jpeg','png','webp'],true)) return $fallback; $dir=__DIR__.'/../assets/uploads'; if(!is_dir($dir)) @mkdir($dir,0755,true); $name='op_'.date('YmdHis').'_'.bin2hex(random_bytes(4)).'.'.$ext; if(move_uploaded_file($_FILES[$field]['tmp_name'],$dir.'/'.$name)) return 'uploads/'.$name; return $fallback; }
if(is_post()){verify_csrf();$image=operator_upload_image('image','safari-card.jpg');if($action==='add_tour'){ $name=trim($_POST['title']);$slug=slugify($name.'-'.uniqid());$dest=(int)$_POST['destination_id'];$desc=trim($_POST['description']);$short=trim($_POST['short_description']);$days=max(1,(int)$_POST['duration_days']);$price=max(0,(float)$_POST['base_price']);$maxGuests=max(1,(int)($_POST['max_guests']??6));query('INSERT INTO tours(operator_id,destination_id,title,slug,short_description,description,duration_days,base_price,max_guests,image,status) VALUES(?,?,?,?,?,?,?,?,?,\'pending\')','iissssidis',[$u['id'],$dest,$name,$slug,$short,$desc,$days,$price,$maxGuests,$image]);flash('success','Tour submitted as pending. Admin can activate it.');redirect('operator/index.php');}
if($action==='add_accommodation'){ $name=trim($_POST['name']);$type=trim($_POST['type']);$loc=trim($_POST['location']);$desc=trim($_POST['description']);$price=max(0,(float)$_POST['price']);$amen=trim($_POST['amenities']);$maxGuests=max(1,(int)($_POST['max_guests']??2));query('INSERT INTO accommodations(operator_id,name,type,location,description,amenities,price_per_night,max_guests,image,status) VALUES(?,?,?,?,?,?,?,?,?,\'pending\')','isssssdis',[$u['id'],$name,$type,$loc,$desc,$amen,$price,$maxGuests,$image]);flash('success','Accommodation submitted.');redirect('operator/index.php?tab=services');}
if($action==='add_transport'){ $name=trim($_POST['name']);$type=trim($_POST['type']);$desc=trim($_POST['description']);$cap=max(1,(int)$_POST['capacity']);$pickup=trim($_POST['pickup']);$price=max(0,(float)$_POST['price']);query('INSERT INTO transports(operator_id,name,type,description,capacity,pickup_area,price,image,status) VALUES(?,?,?,?,?,?,?, ?,\'pending\')','isssisds',[$u['id'],$name,$type,$desc,$cap,$pickup,$price,$image]);flash('success','Transport submitted.');redirect('operator/index.php?tab=services');}
if($action==='add_activity'){ $name=trim($_POST['name']);$desc=trim($_POST['description']);$hours=max(0.5,(float)$_POST['duration_hours']);$price=max(0,(float)$_POST['price']);query("INSERT INTO activities(operator_id,name,description,duration_hours,price,image,status) VALUES(?,?,?,?,?,?, 'pending')",'iissds',[$u['id'],$name,$desc,$hours,$price,$image]);flash('success','Activity submitted.');redirect('operator/index.php?tab=services');}}
$tab=$_GET['tab']??'overview';$dest=query("SELECT * FROM destinations WHERE status='active' ORDER BY name")->fetch_all(MYSQLI_ASSOC);$tours=query("SELECT * FROM tours WHERE operator_id=? ORDER BY id DESC",'i',[$u['id']])->fetch_all(MYSQLI_ASSOC);$acc=query("SELECT * FROM accommodations WHERE operator_id=? ORDER BY id DESC",'i',[$u['id']])->fetch_all(MYSQLI_ASSOC);$trs=query("SELECT * FROM transports WHERE operator_id=? ORDER BY id DESC",'i',[$u['id']])->fetch_all(MYSQLI_ASSOC);$acts=query("SELECT * FROM activities WHERE operator_id=? ORDER BY id DESC",'i',[$u['id']])->fetch_all(MYSQLI_ASSOC);$b=query("SELECT b.*,t.title tour FROM bookings b JOIN tours t ON t.id=b.tour_id WHERE t.operator_id=? ORDER BY b.id DESC",'i',[$u['id']])->fetch_all(MYSQLI_ASSOC);$title=['overview'=>'Operator Dashboard','tours'=>'My Tours','services'=>'Accommodation & Transport','bookings'=>'Bookings','profile'=>'Operator Profile'][$tab]??'Operator Portal';require __DIR__.'/../app/views/portal_header.php';
?>
<?php if($tab==='overview'): ?><div class="section-head"><div><div class="eyebrow" style="color:var(--green)">Partner workspace</div><h1 style="font-family:Georgia,serif">Welcome, <?=e($u['name'])?></h1><p class="muted">Add the experiences and optional services you offer. Admin reviews them before they go live.</p></div></div><div class="stats"><div class="stat"><span class="muted">My tours</span><div class="num"><?=count($tours)?></div></div><div class="stat"><span class="muted">Accommodation</span><div class="num"><?=count($acc)?></div></div><div class="stat"><span class="muted">Transport</span><div class="num"><?=count($trs)?></div></div><div class="stat"><span class="muted">Bookings</span><div class="num"><?=count($b)?></div></div></div><div class="panel" style="margin-top:20px"><h2 style="font-size:30px">Quick actions</h2><div class="actions"><a class="btn btn-dark" href="?tab=tours">Add a tour</a><a class="btn btn-light" href="?tab=services">Add accommodation/transport</a></div></div><?php elseif($tab==='tours'): ?><div class="section-head"><div><div class="eyebrow" style="color:var(--green)">Your inventory</div><h1 style="font-family:Georgia,serif">My Tours</h1></div></div><div class="split"><form class="panel" method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="add_tour"><h2>Add tour</h2><label>Tour name</label><input name="title" required><label>Short description</label><input name="short_description" required><label>Destination</label><select name="destination_id" required><?php foreach($dest as $d): ?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach; ?></select><label>Duration (days)</label><input type="number" name="duration_days" value="1" min="1"><label>Max guests</label><input type="number" name="max_guests" value="6" min="1"><label>Base price / guest</label><input type="number" name="base_price" value="300" step="0.01"><label>Description</label><textarea name="description" required></textarea><label>Image</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"><small class="muted">Upload JPG, PNG or WEBP. A Wildvista sample image is used if none is uploaded.</small><button class="btn btn-dark" style="margin-top:14px">Submit tour</button></form><div class="panel"><h2>Your submitted tours</h2><?php foreach($tours as $t): ?><div class="option"><div><strong><?=e($t['title'])?></strong><div class="muted"><?=money((float)$t['base_price'])?> · <span class="tag <?=($t['status']!=='active'?'pending':'')?>"><?=e($t['status'])?></span></div></div></div><?php endforeach; ?></div></div><?php elseif($tab==='services'): ?><div class="section-head"><div><div class="eyebrow" style="color:var(--green)">Optional trip services</div><h1 style="font-family:Georgia,serif">Accommodation & transport</h1></div></div><div class="split"><form class="panel" method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="add_accommodation"><h2>Add accommodation</h2><label>Name</label><input name="name" required><label>Type</label><input name="type" placeholder="Hotel / Lodge / Private accommodation" required><label>Location</label><input name="location" value="Arusha"><label>Price / night</label><input name="price" type="number" step="0.01" value="120"><label>Max guests</label><input name="max_guests" type="number" value="2"><label>Amenities</label><input name="amenities" placeholder="Wi-Fi, breakfast, parking"><label>Description</label><textarea name="description" required></textarea><label>Image</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"><button class="btn btn-dark">Submit accommodation</button></form><form class="panel" method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="add_transport"><h2>Add transport</h2><label>Name</label><input name="name" required><label>Type</label><input name="type" placeholder="4×4 Safari Vehicle" required><label>Capacity</label><input name="capacity" type="number" value="6"><label>Pickup area</label><input name="pickup" value="Arusha / Airport"><label>Price / booking</label><input name="price" type="number" step="0.01" value="150"><label>Description</label><textarea name="description" required></textarea><label>Image</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"><button class="btn btn-dark">Submit transport</button></form><form class="panel" method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="add_activity"><?=csrf_field()?><h2>Add activity</h2><label>Name</label><input name="name" required><label>Duration (hours)</label><input name="duration_hours" type="number" step="0.5" value="2"><label>Price / guest</label><input name="price" type="number" step="0.01" value="50"><label>Description</label><textarea name="description" required></textarea><label>Image</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"><button class="btn btn-dark">Submit activity</button></form></div><?php elseif($tab==='bookings'): ?><div class="section-head"><div><div class="eyebrow" style="color:var(--green)">Customer activity</div><h1 style="font-family:Georgia,serif">Bookings</h1></div></div><div class="table-wrap"><table><tr><th>Reference</th><th>Customer</th><th>Tour</th><th>Date</th><th>Status</th><th>Total</th></tr><?php foreach($b as $x): ?><tr><td><?=e($x['reference'])?></td><td><?=e($x['customer_name'])?></td><td><?=e($x['tour'])?></td><td><?=e($x['booking_date'])?></td><td><?=e($x['status'])?></td><td><?=money((float)$x['total_amount'])?></td></tr><?php endforeach; ?></table></div><?php endif; ?><?php require __DIR__.'/../app/views/portal_footer.php'; ?>
